CREATE TABLE Department (
  dept_id  INT PRIMARY KEY,
  dname    VARCHAR(40) NOT NULL UNIQUE
);
CREATE TABLE Student (
  roll_no  INT PRIMARY KEY,
  email    VARCHAR(60) UNIQUE,
  name     VARCHAR(50) NOT NULL,
  age      INT CHECK (age BETWEEN 15 AND 60),
  dept_id  INT,
  FOREIGN KEY (dept_id) REFERENCES Department(dept_id)
    ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE TABLE Dept (dept_id INT PRIMARY KEY, dname VARCHAR(30));
CREATE TABLE Emp (
  eid INT PRIMARY KEY, name VARCHAR(30),
  dept_id INT REFERENCES Dept(dept_id),
  mgr_id INT REFERENCES Emp(eid), salary INT
);
ALTER TABLE Emp ADD email VARCHAR(60);
ALTER TABLE Emp DROP COLUMN email;
TRUNCATE TABLE Emp;   -- removes all rows, keeps structure
DROP TABLE Emp;       -- removes rows and the table definition

SELECT e.name, d.dname FROM Emp e INNER JOIN Dept d ON e.dept_id = d.dept_id;
SELECT e.name, d.dname FROM Emp e LEFT JOIN Dept d ON e.dept_id = d.dept_id;
SELECT e.name, d.dname FROM Emp e FULL OUTER JOIN Dept d ON e.dept_id = d.dept_id;
SELECT * FROM Emp NATURAL JOIN Dept;
SELECT e.name AS emp, m.name AS manager
FROM Emp e JOIN Emp m ON e.mgr_id = m.eid;

INSERT INTO Emp (eid, name, dept_id, salary) VALUES (4, 'Gita', 30, 30000);
UPDATE Emp SET salary = salary * 1.10 WHERE dept_id = 10;
DELETE FROM Emp WHERE salary < 10000;
-- subquery: employees earning above the company average
SELECT name FROM Emp WHERE salary > (SELECT AVG(salary) FROM Emp);
-- derived relation in FROM
SELECT t.dept_id, t.total FROM
  (SELECT dept_id, SUM(salary) AS total FROM Emp GROUP BY dept_id) AS t
WHERE t.total > 50000;
